package org.novasos.healthysv2.pharmacy;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.novasos.healthysv2.TestcontainersConfiguration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.oauth2.jwt.*;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test")@SpringBootTest(properties={"spring.security.oauth2.resourceserver.jwt.issuer-uri=https://keycloak.example/realms/healthys","spring.security.oauth2.resourceserver.jwt.audiences=healthys-backend-apps","healthys.security.api-client-id=healthys-backend-apps","healthys.security.cors.allowed-origins=http://localhost:5173"})@AutoConfigureMockMvc@Import({TestcontainersConfiguration.class,PharmacyApiIntegrationTests.JwtFixtures.class})@Transactional class PharmacyApiIntegrationTests{
 static final UUID ADMIN=UUID.fromString("70000000-0000-0000-0000-000000000001");@Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;private final ObjectMapper json=new ObjectMapper().findAndRegisterModules();
 @Test void executesPrescriptionPartialDispenseAndStockWorkflow()throws Exception{Graph g=graph();replenish(g,"10");JsonNode prescription=create(g,"10");UUID prescriptionId=id(prescription,"id"),itemId=id(prescription.path("items").get(0),"id");dispense(g,prescriptionId,itemId,"4").andExpect(status().isCreated()).andExpect(jsonPath("$.items[0].quantityDispensed").value(4));mvc.perform(get("/api/v1/prescriptions/{id}",prescriptionId).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("PARTIALLY_DISPENSED")).andExpect(jsonPath("$.items[0].quantityRemaining").value(6));dispense(g,prescriptionId,itemId,"6").andExpect(status().isCreated());mvc.perform(get("/api/v1/prescriptions/{id}",prescriptionId).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("DISPENSED"));mvc.perform(get("/api/v1/prescriptions/{id}/dispenses",prescriptionId).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(2));mvc.perform(get("/api/v1/medication-stocks").header(HttpHeaders.AUTHORIZATION,"Bearer admin").param("organizationId",g.organization.toString())).andExpect(status().isOk()).andExpect(jsonPath("$[0].quantity").value(0));org.assertj.core.api.Assertions.assertThat(jdbc.queryForObject("select count(*) from audit.audit_log where module='PRESCRIPTION' and entity_type='Prescription' and entity_id=?",Integer.class,prescriptionId)).isEqualTo(3);org.assertj.core.api.Assertions.assertThat(jdbc.queryForObject("select count(*) from audit.audit_log where module='PHARMACY' and entity_type='Dispense' and new_value ->> 'prescriptionId'=?",Integer.class,prescriptionId.toString())).isEqualTo(2);}
 @Test void rejectsInsufficientStockAndSupportsCatalogSearch()throws Exception{Graph g=graph();replenish(g,"5");JsonNode prescription=create(g,"10");dispense(g,id(prescription,"id"),id(prescription.path("items").get(0),"id"),"6").andExpect(status().isUnprocessableContent()).andExpect(jsonPath("$.code").value("INSUFFICIENT_STOCK"));mvc.perform(get("/api/v1/medication-catalog").header(HttpHeaders.AUTHORIZATION,"Bearer admin").param("query","amoxicillin")).andExpect(status().isOk()).andExpect(jsonPath("$[0].code").value("AMOX500"));mvc.perform(get("/api/v1/prescriptions").header(HttpHeaders.AUTHORIZATION,"Bearer admin").param("patientId",g.patient.toString())).andExpect(status().isOk()).andExpect(jsonPath("$.content.length()").value(1));}
 private void replenish(Graph g,String quantity)throws Exception{mvc.perform(post("/api/v1/medication-stocks/replenish").header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"organizationId\":\"%s\",\"medicationCatalogId\":\"%s\",\"batchNumber\":\"LOT-API\",\"quantity\":%s,\"expirationDate\":\"%s\"}".formatted(g.organization,g.medication,quantity,LocalDate.now().plusYears(1)))).andExpect(status().isOk());}private JsonNode create(Graph g,String quantity)throws Exception{String body="{\"patientId\":\"%s\",\"prescriberId\":\"%s\",\"organizationId\":\"%s\",\"expiresAt\":\"%s\",\"items\":[{\"medicationCatalogId\":\"%s\",\"dosage\":\"500 mg\",\"frequency\":\"Twice daily\",\"route\":\"ORAL\",\"duration\":\"5 days\",\"quantity\":%s}]}".formatted(g.patient,g.doctor,g.organization,Instant.now().plus(Duration.ofDays(30)),g.medication,quantity);return json.readTree(mvc.perform(post("/api/v1/prescriptions").header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.items[0].medicationCode").value("AMOX500")).andReturn().getResponse().getContentAsString());}private org.springframework.test.web.servlet.ResultActions dispense(Graph g,UUID prescription,UUID item,String quantity)throws Exception{return mvc.perform(post("/api/v1/prescriptions/{id}/dispenses",prescription).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"pharmacyOrganizationId\":\"%s\",\"pharmacistId\":\"%s\",\"items\":[{\"prescriptionItemId\":\"%s\",\"quantityDispensed\":%s,\"batchNumber\":\"LOT-API\"}]}".formatted(g.organization,g.pharmacist,item,quantity)));}private UUID id(JsonNode n,String field){return UUID.fromString(n.path(field).asText());}
 private Graph graph(){UUID pp=person(),dp=person(),php=person(),patient=UUID.randomUUID(),doctor=professional(dp,"DOCTOR"),pharmacist=professional(php,"PHARMACIST"),organization=UUID.randomUUID(),medication=UUID.randomUUID();jdbc.update("insert into patient.patient(id,person_id,patient_number) values (?,?,?)",patient,pp,"PAT-"+patient);jdbc.update("insert into organization.organization(id,organization_number,name) values (?,?,?)",organization,"ORG-"+organization,"Pharmacy");jdbc.update("insert into professional.professional_assignment(id,professional_id,organization_id,start_date,status) values (?,?,?,?,?)",UUID.randomUUID(),pharmacist,organization,LocalDate.now(),"ACTIVE");jdbc.update("insert into catalog.medication_catalog(id,code,name,generic_name,form,strength,active) values (?,?,?,?,?,?,?)",medication,"AMOX500","Amoxicillin 500 mg","Amoxicillin","CAPSULE","500 mg",true);return new Graph(patient,doctor,pharmacist,organization,medication);}private UUID person(){UUID id=UUID.randomUUID();jdbc.update("insert into identity.person(id,person_number,first_name,last_name,status) values (?,?,?,?,?)",id,"PER-"+id,"Test","User","ACTIVE");return id;}private UUID professional(UUID person,String type){UUID id=UUID.randomUUID();jdbc.update("insert into professional.professional(id,person_id,professional_number,professional_type,status) values (?,?,?,?,?)",id,person,"PRO-"+id,type,"ACTIVE");return id;}record Graph(UUID patient,UUID doctor,UUID pharmacist,UUID organization,UUID medication){}
 @TestConfiguration(proxyBeanMethods=false)static class JwtFixtures{@Bean JwtDecoder jwtDecoder(){return token->{Instant now=Instant.now();return Jwt.withTokenValue(token).header("alg","RS256").subject(ADMIN.toString()).issuer("https://keycloak.example/realms/healthys").audience(List.of("healthys-backend-apps")).issuedAt(now).expiresAt(now.plusSeconds(300)).claim("realm_access",Map.of("roles",List.of("PLATFORM_ADMIN"))).claim("resource_access",Map.of()).build();};}}
}
